<?php
declare(strict_types=1);
// Stability experiment: every failed iteration remains a failure; no successful retry erases it.
$suite=$argv[1]??'';$count=filter_var($argv[2]??'',FILTER_VALIDATE_INT);
if(!in_array($suite,['commerce-http','services-http','session-concurrency'],true)||$count===false||$count<1||$count>100){fwrite(STDERR,"Expected commerce-http|services-http|session-concurrency and 1..100 iterations\n");exit(2);}
$root=dirname(__DIR__);$directory=$root.'/storage/ci-stability';if(!is_dir($directory)){mkdir($directory,0700,true);}$results=[];$failed=0;
for($iteration=1;$iteration<=$count;++$iteration){$pipes=[];$start=hrtime(true);$process=proc_open([PHP_BINARY,$root.'/tests/'.$suite.'.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,$root);fclose($pipes[0]);$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($process);$failureNames=[];preg_match_all('/^FAIL ([^:\r\n]+)/m',$stdout,$matches);$failureNames=$matches[1];$results[]=['iteration'=>$iteration,'exit'=>$exit,'duration_ms'=>(hrtime(true)-$start)/1e6,'failed_tests'=>$failureNames,'stdout_sha256'=>hash('sha256',$stdout),'stderr_bytes'=>strlen($stderr),'stderr_sha256'=>hash('sha256',$stderr)];echo $suite.' iteration '.$iteration.'/'.$count.' exit='.$exit.PHP_EOL;if($exit!==0){++$failed;echo $stdout;echo 'Child stderr bytes='.strlen($stderr).' sha256='.hash('sha256',$stderr).PHP_EOL;}}
$summary=['suite'=>$suite,'php'=>PHP_VERSION,'os'=>PHP_OS_FAMILY,'iterations'=>$count,'failed_iterations'=>$failed,'results'=>$results];file_put_contents($directory.'/'.$suite.'-'.PHP_VERSION.'-'.bin2hex(random_bytes(4)).'.json',json_encode($summary,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));echo $count.' iterations; '.$failed.' failed (failures are not retried away)'.PHP_EOL;exit($failed===0?0:1);
